# AI Office v2.6 Part D Context Assembly Installer
$ErrorActionPreference="Stop"
$Repository="E:\AI\AI-Office"
Set-Location $Repository
$Stamp=Get-Date -Format "yyyyMMdd-HHmmss"
$Backup=Join-Path $Repository ("workspace\installer-backups\v2.6-part-d-"+$Stamp)
New-Item -ItemType Directory -Path $Backup -Force|Out-Null
function Write-EmbeddedFile{
 param([string]$RelativePath,[string]$Data)
 $Dest=Join-Path $Repository $RelativePath
 New-Item -ItemType Directory -Path (Split-Path -Parent $Dest) -Force|Out-Null
 if(Test-Path $Dest){
  $B=Join-Path $Backup $RelativePath
  New-Item -ItemType Directory -Path (Split-Path -Parent $B) -Force|Out-Null
  Copy-Item $Dest $B -Force
 }
 [IO.File]::WriteAllBytes($Dest,[Convert]::FromBase64String($Data))
 Write-Host "[WRITTEN] $RelativePath" -ForegroundColor Green
}
Write-EmbeddedFile -RelativePath "config\memory\context-assembly-policy.json" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\New-AIOfficeContextSnapshotId.ps1" -Data "cGFyYW0oKQpyZXR1cm4gKCJDVFgtIiArIChHZXQtRGF0ZSAtRm9ybWF0ICJ5eXl5TU1kZC1ISG1tc3MiKSArICItIiArIFtndWlkXTo6TmV3R3VpZCgpLlRvU3RyaW5nKCJOIikuU3Vic3RyaW5nKDAsNikuVG9VcHBlckludmFyaWFudCgpKQo="
Write-EmbeddedFile -RelativePath "scripts\memory\New-AIOfficeMemoryContextPackage.ps1" -Data ""
Write-EmbeddedFile -RelativePath "scripts\memory\Test-AIOfficeContextAssembly.ps1" -Data ""
Write-EmbeddedFile -RelativePath "docs\AI-Office-v2.6-Part-D-Context-Assembly.md" -Data ""
$Scripts=Get-ChildItem "E:\AI\AI-Office\scripts\memory\*.ps1" -File
foreach($Script in $Scripts){$T=$null;$E=$null;[System.Management.Automation.Language.Parser]::ParseFile($Script.FullName,[ref]$T,[ref]$E)|Out-Null;if($E.Count-gt0){throw ("Syntax error in "+$Script.FullName+": "+(($E|ForEach-Object{$_.Message})-join"; "))}}
Write-Host ""
Write-Host "AI Office v2.6 Part D Context Assembly installed successfully." -ForegroundColor Green
Write-Host "Bounded context packages are available; live prompt injection remains disabled." -ForegroundColor Cyan
Write-Host "Backups: $Backup" -ForegroundColor Cyan